    expect(config.credentials).toBe("include");
    expect(await config.headers()).toEqual({ "X-Changmen-Auth": "cookie", "X-CSRF-Token": "csrf" });
  });
  test("rejects Safe/Proxy signature types", async () => {
    const result = await preparePolymarketWalletUnified({
      privateKey: `0x${"11".repeat(32)}`,
      signUrl: "https://example.com/api/polymarket/relayer/sign",
      authToken: "tok",
      signatureType: 2,
    });
    expect(result.ok).toBe(false);
    expect(result.message).toMatch(/signatureType=3/);
    expect(createSecureClient).not.toHaveBeenCalled();
  });

  test("deploys via createSecureClient + setupTradingApprovals", async () => {
    createSecureClient.mockResolvedValue({
      account: { wallet: "0xDepositWallet11111111111111111111111111" },
      setupTradingApprovals,
    });

    const result = await preparePolymarketWalletUnified({
      privateKey: `0x${"11".repeat(32)}`,
      signUrl: "https://example.com/api/polymarket/relayer/sign",
      authToken: "tok",
      signatureType: 3,
      relayerUrl: "https://relayer-custom.example.com",
      credentials: {
        key: "k",
        secret: "s",
        passphrase: "p",
      },
    });

    expect(result.ok).toBe(true);
    expect(result.funder).toBe("0xDepositWallet11111111111111111111111111");
    expect(createSecureClient).toHaveBeenCalledTimes(1);
    expect(setupTradingApprovals).toHaveBeenCalledTimes(1);
    expect(remoteBuilderSigning).toHaveBeenCalledWith(expect.objectContaining({
      url: "https://example.com/api/polymarket/relayer/sign",
    }));
    const secureOpts = createSecureClient.mock.calls[0]?.[0] as {
      credentials?: { key: string };
      environment?: { rpc?: string; relayer?: { rest?: string } };
    };
    expect(secureOpts.credentials?.key).toBe("k");
    expect(secureOpts.environment?.relayer?.rest).toBe("https://relayer-custom.example.com");
    expect(String(secureOpts.environment?.rpc || "")).toMatch(/^https?:\/\//);
  });

  test("maps CLOB/network failures to actionable message", async () => {
    createSecureClient.mockRejectedValue(new Error("Failed to fetch"));
    const result = await preparePolymarketWalletUnified({
      privateKey: `0x${"11".repeat(32)}`,
      signUrl: "https://example.com/api/polymarket/relayer/sign",
      authToken: "tok",
      signatureType: 3,
    });
    expect(result.ok).toBe(false);
    expect(result.message).toMatch(/可达 CLOB/);
    expect(result.message).toMatch(/legacy/);
  });
});

import type {
  RelayClient,
  RelayerTxType,
  DepositWalletCall,
} from "@polymarket/builder-relayer-client";
import { encodeFunctionData, maxUint256, type Hex } from "viem";
import { POLYGON_POLYMARKET, polymarketTradeSpenders } from "./contracts";
import { deriveDepositWalletAddress } from "./depositWalletAddress";
import {
  createPolygonHttpTransport,
  patchRelayClientPublicClient,
  polygonChainForRpc,
} from "./polygonRpc";

export const POLYMARKET_RELAYER_URL_DEFAULT = "https://relayer-v2.polymarket.com";
export const POLYGON_CHAIN_ID = 137;

const ERC20_APPROVE_ABI = [
  {
    name: "approve",
    type: "function",
    inputs: [
      { name: "spender", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [{ type: "bool" }],
  },
] as const;

const ERC1155_SET_APPROVAL_FOR_ALL_ABI = [
  {
    name: "setApprovalForAll",
    type: "function",
    inputs: [
      { name: "operator", type: "address" },
      { name: "approved", type: "bool" },
    ],
    outputs: [],
  },
] as const;

export function normalizePolymarketPrivateKey(raw: string): Hex {
  const key = raw.trim();
  const hex = key.startsWith("0x") ? key : `0x${key}`;
  if (!/^0x[0-9a-fA-F]{64}$/.test(hex))
    throw new Error("Polymarket 私钥格式不正确，应为 64 位 hex");
  return hex as Hex;
}

export async function resolvePolymarketSignerAddress(privateKey: string): Promise<string> {
  const accounts = await import("viem/accounts");
  return accounts.privateKeyToAccount(normalizePolymarketPrivateKey(privateKey)).address;
}

function joinSignUrl(signUrl: string): string {
  const url = signUrl.trim();
  if (!url.startsWith("http://") && !url.startsWith("https://"))
    throw new Error("Relayer 远程签名 URL 必须是绝对地址");
  return url;
}

export interface PolymarketRelayClientInput {
  privateKey: string;
  signUrl?: string;
  authToken?: string;
  getAuthToken?: () => Promise<string>;
  getAuthHeaders?: () => Promise<Record<string, string>>;
  relayerUrl?: string;
  relayTxType?: RelayerTxType;
}

/**
 * [官方] docs / README：`transport: http(process.env.RPC_URL)`，勿依赖 viem 默认 polygon.drpc.org。
 * RelayClient 第 6 参 `options.chain` 供其内部 publicClient 读 rpcUrls。
 */
export async function createPolymarketRelayClient(
  input: PolymarketRelayClientInput,
): Promise<RelayClient> {
  const privateKey = normalizePolymarketPrivateKey(input.privateKey);
  const relayerUrl = (input.relayerUrl?.trim() || POLYMARKET_RELAYER_URL_DEFAULT).replace(/\/+$/, "");
  const [
    accounts,
    viem,
    { RelayClient },
    { BuilderConfig },
    { SessionBuilderConfig },
  ] = await Promise.all([
    import("viem/accounts"),
    import("viem"),
    import("@polymarket/builder-relayer-client"),
    import("@polymarket/builder-signing-sdk"),
    import("./sessionBuilderConfig"),
  ]);
  const account = accounts.privateKeyToAccount(privateKey);
  const chain = polygonChainForRpc();
  const wallet = viem.createWalletClient({
    account,
    chain,
    transport: createPolygonHttpTransport(),
  });
  const signUrl = input.signUrl?.trim();
  const authToken = input.authToken?.trim();
  const builderConfig = signUrl && (authToken || input.getAuthHeaders)
    ? input.getAuthToken || input.getAuthHeaders ? new SessionBuilderConfig(joinSignUrl(signUrl), input.getAuthToken, input.getAuthHeaders) : new BuilderConfig({
        remoteBuilderConfig: {
          url: joinSignUrl(signUrl),
          token: authToken,
        },
      })
    : undefined;
  const client = new RelayClient(
    relayerUrl,
    POLYGON_CHAIN_ID,
    wallet,
    builderConfig,
    input.relayTxType,
    { chain },
  );
  // SDK 内 publicClient 无 fallback；替换后 deriveDepositWalletAddress eth_call 才走多节点
  patchRelayClientPublicClient(client, chain);
  return client;
}

/** [changmen 扩展] 与官方 SDK 相同的 beacon / UUPS 判断，旧 SDK 不进入地址派生路径。 */
export async function derivePolymarketDepositWalletAddress(input: {
  privateKey: string;
  relayerUrl?: string;
}): Promise<string> {
  const owner = await resolvePolymarketSignerAddress(input.privateKey);
  return deriveDepositWalletAddress(owner as Hex);
}

export async function resolvePolymarketDepositWalletFromPrivateKey(input: {
  privateKey: string;
  relayerUrl?: string;
}): Promise<{ walletAddress: string; funder: string }> {
  const walletAddress = await resolvePolymarketSignerAddress(input.privateKey);
  const funder = await derivePolymarketDepositWalletAddress(input);
  return { walletAddress, funder };
}

function createDepositWalletApproveCall(tokenAddress: string, spenderAddress: string): DepositWalletCall {
  return {
    target: tokenAddress,
    value: "0",
    data: encodeFunctionData({
      abi: ERC20_APPROVE_ABI,
      functionName: "approve",
      args: [spenderAddress as Hex, maxUint256],
    }),
  };
}

function createDepositWalletSetApprovalForAllCall(operatorAddress: string): DepositWalletCall {
  return {
    target: POLYGON_POLYMARKET.CTF,
    value: "0",
    data: encodeFunctionData({
      abi: ERC1155_SET_APPROVAL_FOR_ALL_ABI,
      functionName: "setApprovalForAll",
      args: [operatorAddress as Hex, true],
    }),
  };
}

/** Deposit Wallet batch：买（collateral approve）+ 卖（CTF setApprovalForAll） */
export function buildDepositWalletApprovalCalls(): DepositWalletCall[] {
  const spenders = polymarketTradeSpenders();
  const calls: DepositWalletCall[] = [
    createDepositWalletApproveCall(POLYGON_POLYMARKET.USDC, POLYGON_POLYMARKET.CTF),
    createDepositWalletApproveCall(POLYGON_POLYMARKET.PUSD, POLYGON_POLYMARKET.CTF),
  ];
  for (const spender of spenders) {
    calls.push(createDepositWalletApproveCall(POLYGON_POLYMARKET.USDC, spender));
    calls.push(createDepositWalletApproveCall(POLYGON_POLYMARKET.PUSD, spender));
    calls.push(createDepositWalletSetApprovalForAllCall(spender));
  }
  return calls;
}

/**
 * Polymarket 钱包准备（Relayer / Deposit Wallet）SDK 选型。
 *
 * - unified（默认）：@polymarket/client（createSecureClient / remoteBuilderSigning）
 * - legacy：显式回滚使用 @polymarket/builder-relayer-client + builder-signing-sdk
 *
 * 下单热路径（bet.ts / pmTransport）不走此开关。
 * 切换：localStorage PM_WALLET_PREP_SDK 或 VITE_PM_WALLET_PREP_SDK
 */

export type PmWalletPrepSdk = "legacy" | "unified";

const LS_KEY = "PM_WALLET_PREP_SDK";

let testOverride: PmWalletPrepSdk | null = null;

function normalizeSdk(raw: string | undefined | null): PmWalletPrepSdk | null {
  const v = String(raw ?? "").trim().toLowerCase();
  if (v === "legacy" || v === "v2" || v === "relay")
    return "legacy";
  if (v === "unified" || v === "client" || v === "ts-sdk")
    return "unified";
  return null;
}

/** [changmen 扩展] 用户账号使用 Deposit Wallet，默认官方 unified SDK；legacy 仅显式回滚。 */
export function resolvePmWalletPrepSdk(): PmWalletPrepSdk {
  if (testOverride)
    return testOverride;
  if (typeof globalThis.localStorage !== "undefined") {
    const fromLs = normalizeSdk(globalThis.localStorage.getItem(LS_KEY));
    if (fromLs)
      return fromLs;
  }
  const env = typeof import.meta !== "undefined"
    ? normalizeSdk((import.meta as ImportMeta & { env?: Record<string, string> }).env?.VITE_PM_WALLET_PREP_SDK)
    : null;
  if (env)
    return env;
  return "unified";
}

export function setPmWalletPrepSdkForTests(sdk: PmWalletPrepSdk | null): void {
  testOverride = sdk;
}

export function setPmWalletPrepSdk(sdk: PmWalletPrepSdk): void {
  try {
    globalThis.localStorage?.setItem(LS_KEY, sdk);
  }
  catch {
    /* ignore */
  }
}

import type { Chain, Transport } from "viem";
import { createPublicClient, fallback, http } from "viem";
import { polygon } from "viem/chains";

/**
 * Polygon RPC（对齐官方 Relayer 示例：`http(process.env.RPC_URL)`）。
 * viem 默认 `polygon.drpc.org` 在部分网络会 eth_call unavailable；
 * 未配置时用公共节点 fallback，仅服务「推导/部署 Deposit Wallet」等读链场景。
 */
export const POLYGON_RPC_URLS = [
  "https://polygon-bor.publicnode.com",
  "https://polygon.llamarpc.com",
  "https://polygon.drpc.org",
] as const;

function readVitePolygonRpcUrl(): string {
  try {
    // Vite / Vitest 会在构建期内联；Node 侧通常无此项
    const env = (import.meta as ImportMeta & { env?: Record<string, string | undefined> }).env;
    return String(env?.VITE_POLYGON_RPC_URL ?? "").trim();
  }
  catch {
    return "";
  }
}

function readConfiguredPolygonRpcUrl(): string {
  let fromProcess = "";
  if (typeof process !== "undefined" && process.env) {
    fromProcess = String(
      process.env.RPC_URL
      || process.env.POLYGON_RPC_URL
      || process.env.POLYMARKET_POLYGON_RPC
      || process.env.VITE_POLYGON_RPC_URL
      || "",
    ).trim();
  }
  return fromProcess || readVitePolygonRpcUrl();
}

export function resolvePolygonRpcUrls(): string[] {
  const configured = readConfiguredPolygonRpcUrl();
  if (!configured)
    return [...POLYGON_RPC_URLS];
  return [configured, ...POLYGON_RPC_URLS.filter(url => url !== configured)];
}

/** 钱包签名 / 读链：多 RPC fallback */
export function createPolygonHttpTransport(): Transport {
  return fallback(resolvePolygonRpcUrls().map(url => http(url)));
}

export function polygonChainForRpc(): Chain {
  const urls = resolvePolygonRpcUrls();
  return {
    ...polygon,
    rpcUrls: {
      ...polygon.rpcUrls,
      default: { http: urls },
    },
  };
}

/**
 * `@polymarket/builder-relayer-client` RelayClient 构造时固定
 * `transport: http()`（只吃 chain.rpcUrls.default.http[0]）。
 * 构造后替换 publicClient，使 deriveDepositWalletAddress 的 eth_call 走 fallback。
 */
export function patchRelayClientPublicClient(client: object, chain: Chain = polygonChainForRpc()): void {
  Reflect.set(client, "publicClient", createPublicClient({
    chain,
    transport: createPolygonHttpTransport(),
  }));
}

