  assert.equal(s.tradeCount, 2);
  assert.equal(s.volumeUsdc, 15);
  assert.ok(Math.abs(s.feeUsdc - 0.15) < 1e-9);
  assert.ok(Math.abs(s.builderFeeUsdc - 0.07) < 1e-9);
  assert.equal(s.buyCount, 1);
  assert.equal(s.sellCount, 1);
  assert.equal(s.buyVolumeUsdc, 10);
  assert.equal(s.sellVolumeUsdc, 5);
  assert.ok(Math.abs(s.buyFeeUsdc - 0.1) < 1e-9);
  assert.ok(Math.abs(s.sellFeeUsdc - 0.05) < 1e-9);
  assert.ok(Math.abs(s.buyBuilderFeeUsdc - 0.05) < 1e-9);
  assert.ok(Math.abs(s.sellBuilderFeeUsdc - 0.02) < 1e-9);
});

import { requireHttpUser as requireAuthedUser } from "../../auth/http_identity.js";
import {
  getPolymarketRelayerPublicStatus,
  signPolymarketRelayerRequest,
} from "./relayer_sign.js";
import { getPolymarketRelayerUrl } from "./relayer_config.js";

/**
 * POST /api/polymarket/relayer/sign
 * Body JSON: { method, path, body?, timestamp? }
 * 供 @polymarket/builder-relayer-client 的 remoteBuilderConfig 调用。
 */
export async function handlePolymarketRelayerSign(req, res, readJsonBody) {
  if (req.method !== "POST") {
    res.writeHead(405, { "Content-Type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ error: "method not allowed" }));
    return true;
  }

  const auth = await requireAuthedUser(req);
  if (auth.error) {
    res.writeHead(auth.error.status, { "Content-Type": "application/json; charset=utf-8" });
    res.end(JSON.stringify(auth.error.body));
    return true;
  }

  let payload;
  try {
    payload = await readJsonBody(req);
  }
  catch (err) {
    res.writeHead(400, { "Content-Type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ error: err.message || "invalid JSON body" }));
    return true;
  }

  const signed = await signPolymarketRelayerRequest(payload);
  if (!signed.ok) {
    res.writeHead(signed.msg.includes("未配置") ? 503 : 400, {
      "Content-Type": "application/json; charset=utf-8",
    });
    res.end(JSON.stringify({ error: signed.msg }));
    return true;
  }

  res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(signed.headers));
  return true;
}

/** GET /api/polymarket/relayer/status */
export async function handlePolymarketRelayerStatus(req, res) {
  if (req.method !== "GET") {
    res.writeHead(405, { "Content-Type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ error: "method not allowed" }));
    return true;
  }

  const auth = await requireAuthedUser(req);
  if (auth.error) {
    res.writeHead(auth.error.status, { "Content-Type": "application/json; charset=utf-8" });
    res.end(JSON.stringify(auth.error.body));
    return true;
  }

  res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify({
    ...getPolymarketRelayerPublicStatus(),
    relayerUrl: getPolymarketRelayerUrl(),
  }));
  return true;
}

import { BuilderSigner } from "@polymarket/builder-signing-sdk";
import {
  getPolymarketRelayerAuthMode,
  isPolymarketRelayerConfigured,
  loadPolymarketBuilderCreds,
  loadPolymarketRelayerApiKeyAuth,
} from "./relayer_config.js";
import { signPolymarketRelayerRequestUnified } from "./relayer_sign_unified.js";

/**
 * Relayer HMAC 实现选型。默认 legacy（builder-signing-sdk）。
 * 备选 unified → relayer_sign_unified.js（@polymarket/client.buildHmacSignature）。
 * 环境变量：POLYMARKET_RELAYER_SIGN_SDK=legacy|unified
 */
export function resolvePolymarketRelayerSignSdk() {
  const raw = String(process.env.POLYMARKET_RELAYER_SIGN_SDK || "").trim().toLowerCase();
  if (raw === "unified" || raw === "client" || raw === "ts-sdk")
    return "unified";
  return "legacy";
}

/**
 * 返回 Relayer 请求头。SDK remoteBuilderConfig / remoteBuilderSigning 会 POST 到此逻辑。
 * - relayer_api_key：固定两 header，无需 HMAC
 * - builder_hmac：按 method/path/body 算 POLY_BUILDER_* 签名
 *
 * @param {{ method?: string, path?: string, body?: string, timestamp?: number }} payload
 * @returns {Promise<{ ok: true, headers: Record<string, string> } | { ok: false, msg: string }>}
 */
export async function signPolymarketRelayerRequest(payload) {
  const mode = getPolymarketRelayerAuthMode();
  if (mode === "relayer_api_key") {
    const relayerHeaders = loadPolymarketRelayerApiKeyAuth();
    if (relayerHeaders)
      return { ok: true, headers: { ...relayerHeaders } };
  }

  if (resolvePolymarketRelayerSignSdk() === "unified")
    return signPolymarketRelayerRequestUnified(payload);

  const creds = loadPolymarketBuilderCreds();
  if (!creds) {
    return {
      ok: false,
      msg: "Polymarket Relayer 未配置（changmen 推荐 POLY_BUILDER_* 三组；或 RELAYER_API_KEY + 与用户私钥同地址的 ADDRESS）",
    };
  }

  const method = String(payload?.method || "").trim().toUpperCase();
  const path = String(payload?.path || "").trim();
  if (!method || !path)
    return { ok: false, msg: "缺少 method 或 path" };

  const body = payload?.body === undefined || payload?.body === null
    ? undefined
    : String(payload.body);
  const timestamp = payload?.timestamp === undefined || payload?.timestamp === null
    ? undefined
    : Number(payload.timestamp);

  const signer = new BuilderSigner(creds);
  const headers = signer.createBuilderHeaderPayload(
    method,
    path,
    body,
    Number.isFinite(timestamp) ? timestamp : undefined,
  );
  return { ok: true, headers };
}

export function getPolymarketRelayerPublicStatus() {
  return {
    configured: isPolymarketRelayerConfigured(),
    authMode: getPolymarketRelayerAuthMode(),
    signSdk: resolvePolymarketRelayerSignSdk(),
  };
}

import assert from "node:assert/strict";
import { afterEach, it } from "vitest";
import { BuilderSigner } from "@polymarket/builder-signing-sdk";
import {
  getPolymarketRelayerPublicStatus,
  resolvePolymarketRelayerSignSdk,
  signPolymarketRelayerRequest,
} from "./relayer_sign.js";

const ENV_KEYS = [
  "RELAYER_API_KEY",
  "RELAYER_API_KEY_ADDRESS",
  "POLY_BUILDER_API_KEY",
  "POLY_BUILDER_SECRET",
  "POLY_BUILDER_PASSPHRASE",
  "POLYMARKET_RELAYER_SIGN_SDK",
];

function clearRelayerEnv() {
  for (const key of ENV_KEYS)
    delete process.env[key];
}

afterEach(() => {
  clearRelayerEnv();
});

it("signPolymarketRelayerRequest fails when creds missing", async () => {
  clearRelayerEnv();
  const r = await signPolymarketRelayerRequest({ method: "POST", path: "/submit" });
  assert.equal(r.ok, false);
  assert.match(r.msg, /未配置/);
});

it("signPolymarketRelayerRequest returns RELAYER_API_KEY headers (preferred)", async () => {
  process.env.RELAYER_API_KEY = "01967c03-b8c8-7000-8f68-8b8eaec6fd3d";
  process.env.RELAYER_API_KEY_ADDRESS = "0x8ed24e533d24c2f381983eda8f97c2358f8d65e5";
  const r = await signPolymarketRelayerRequest({ method: "POST", path: "/submit" });
  assert.equal(r.ok, true);
  assert.equal(r.headers.RELAYER_API_KEY, "01967c03-b8c8-7000-8f68-8b8eaec6fd3d");
  assert.equal(r.headers.RELAYER_API_KEY_ADDRESS, "0x8ed24e533d24c2f381983eda8f97c2358f8d65e5");
  assert.equal(r.headers.POLY_BUILDER_API_KEY, undefined);
});

it("signPolymarketRelayerRequest returns POLY_BUILDER_* when no relayer key", async () => {
  process.env.POLY_BUILDER_API_KEY = "test-key";
  process.env.POLY_BUILDER_SECRET = "dGVzdC1zZWNyZXQ=";
  process.env.POLY_BUILDER_PASSPHRASE = "test-pass";
