/**
 * 统一 SDK Relayer HMAC（@polymarket/client.buildHmacSignature）。
 * 与 BuilderSigner.createBuilderHeaderPayload 签名结果一致；响应字段保持 POLY_BUILDER_*。
 *
 * 启用：POLYMARKET_RELAYER_SIGN_SDK=unified
 */

import { buildHmacSignature } from "@polymarket/client";
import { loadPolymarketBuilderCreds } from "./relayer_config.js";

/**
 * @param {{ method?: string, path?: string, body?: string, timestamp?: number }} payload
 * @returns {Promise<{ ok: true, headers: Record<string, string> } | { ok: false, msg: string }>}
 */
export async function signPolymarketRelayerRequestUnified(payload) {
  const creds = loadPolymarketBuilderCreds();
  if (!creds) {
    return {
      ok: false,
      msg: "Polymarket Relayer 未配置（changmen 推荐 POLY_BUILDER_* 三组；或 RELAYER_API_KEY + 与用户私钥同地址的 ADDRESS）",
    };
  }

  const method = String(payload?.method || "").trim().toUpperCase();
  const path = String(payload?.path || "").trim();
  if (!method || !path)
    return { ok: false, msg: "缺少 method 或 path" };

  const body = payload?.body === undefined || payload?.body === null
    ? undefined
    : String(payload.body);
  const timestamp = payload?.timestamp === undefined || payload?.timestamp === null
    ? Math.floor(Date.now() / 1000)
    : Number(payload.timestamp);
  if (!Number.isFinite(timestamp))
    return { ok: false, msg: "timestamp 无效" };

  const signature = await buildHmacSignature(
    creds.secret,
    timestamp,
    method,
    path,
    body,
  );

  return {
    ok: true,
    headers: {
      POLY_BUILDER_API_KEY: creds.key,
      POLY_BUILDER_PASSPHRASE: creds.passphrase,
      POLY_BUILDER_SIGNATURE: signature,
      POLY_BUILDER_TIMESTAMP: String(Math.floor(timestamp)),
    },
  };
}

/** Keep migrated implementations and their compatibility exports in the same layer. */
export function venueManualChunk(id: string): string | undefined {
  const normalized = id.replace(/\\/g, "/");
  if ([
    "packages/arb-core/", "@changmen/arb-core/",
    "packages/client-core/", "@changmen/client-core/",
    "packages/shared/", "@changmen/shared/",
    "packages/api-contract/", "@changmen/api-contract/",
  ].some(marker => normalized.includes(marker))) {
    return "venue-shared";
  }
  // socket.io is also used by the shared hub. Assigning it to a venue can cause TDZ errors.
  if (["socket.io-client", "engine.io-client", "socket.io-parser"]
    .some(pkg => normalized.includes(`/node_modules/${pkg}/`))) {
    return "venue-shared";
  }
  // Nested workspace dependencies must remain under Rollup's automatic assignment.
  if (normalized.includes("/node_modules/")) return undefined;

  const marker = "client/packages/venue-browser/";
  const index = normalized.indexOf(marker);
  if (index < 0) return undefined;
  const relative = normalized.slice(index + marker.length);
  // This class extends the legacy signing SDK. Keep its dynamic import outside
  // the eager venue chunk so Deposit Wallet derivation/unified prep stay ESM-only.
  if (relative === "polymarket/wallet/sessionBuilderConfig.ts"
    || relative === "adapter/polymarket/wallet/sessionBuilderConfig.ts") return undefined;
  if (relative.startsWith("shared/") || relative.startsWith("contract/"))
    return "venue-shared";
  if (relative.startsWith("polymarket/")) return "venue-polymarket";
  if (!relative.startsWith("adapter/")) return undefined;

  const dir = relative.slice("adapter/".length).split("/")[0];
  if (!dir || dir === "registry" || dir === "adaptation") return undefined;
  if (dir === "shared" || dir === "contract") return "venue-shared";
  return `venue-${dir}`;
}

