it("keeps the legacy wallet signing class and its SDK outside the initial static import graph", async () => {
  const session = root + "polymarket/wallet/sessionBuilderConfig.ts";
  const sdk = "/fixture/node_modules/legacy-signing-sdk/index.js";
  const modules: Record<string, string> = {
    [entry]: `import { derive, legacy } from '${runtime}'; globalThis.address = derive(); globalThis.openLegacy = legacy;`,
    [runtime]: `export const derive = () => 'deposit-wallet'; export const legacy = () => import('${session}');`,
    [session]: `import { Builder } from '${sdk}'; export class Session extends Builder {}`,
    [sdk]: "globalThis.legacySdkLoaded = true; export class Builder {}",
  };
  const bundle = await rollup({ input: entry, plugins: [{ name: "deferred-wallet-fixture",
    resolveId: id => Object.hasOwn(modules, id) ? id : null, load: id => modules[id],
  }, acyclicChunks()] });
  try {
    const { output } = await bundle.generate({ format: "es", manualChunks: venueManualChunk });
    const chunks = output.filter(item => item.type === "chunk");
    const initial = new Set<string>();
    const visit = (file: string): void => {
      if (initial.has(file)) return;
      initial.add(file);
      chunks.find(chunk => chunk.fileName === file)?.imports.forEach(visit);
    };
    chunks.filter(chunk => chunk.isEntry).forEach(chunk => visit(chunk.fileName));
    const loaded = chunks.filter(chunk => initial.has(chunk.fileName)).flatMap(chunk => Object.keys(chunk.modules));
    expect(loaded).toContain(runtime);
    expect(loaded).not.toContain(session);
    expect(loaded).not.toContain(sdk);
    expect(chunks.some(chunk => !initial.has(chunk.fileName) && Object.hasOwn(chunk.modules, sdk))).toBe(true);
  }
  finally { await bundle.close(); }
});

